// =========================================================
// TEMPLATE CALIBRATION ENGINE
// =========================================================
// Circle detection remains the locked baseline detector.
// Text zones are calibrated per template and persisted locally.
const CALIBRATION_VERSION = 1;

const cloneLayout = (templateNo) => ({
  photo: {
    leaderCircle: { ...(getTemplatePhotoCoords(templateNo).leaderCircle) },
    achieverCircle: { ...(getTemplatePhotoCoords(templateNo).achieverCircle) }
  },
  text: {
    leaderNameBox: { ...EXACT_COORDS.leaderNameBox },
leaderCityBox: { ...EXACT_COORDS.leaderCityBox },
achieverNameBox: { ...EXACT_COORDS.achieverNameBox },
achieverRankBox: { ...EXACT_COORDS.achieverRankBox },
phoneBox: { ...EXACT_COORDS.phoneBox }
  },
  version: CALIBRATION_VERSION
});

const calibrationStorageKey = (rankName, templateNo) =>
  `aarsh-template-calibration-v${CALIBRATION_VERSION}:${getRankSlug(rankName)}:${templateNo}`;

const loadCalibration = (rankName, templateNo) => {
  try {
    // Read the layout saved by the standalone Calibration Studio first,
    // while keeping the original Aarsh calibration key fully compatible.
    const legacyKey = calibrationStorageKey(rankName, templateNo);
    const standaloneKey = `aarsh-calibration-v2:${getRankSlug(rankName)}:${templateNo}`;
    const staticStandaloneKey = `aarsh-calibration-v2:rank_${getRankSlug(rankName)}:${templateNo}`;
    const raw =
      localStorage.getItem(legacyKey) ||
      localStorage.getItem(standaloneKey) ||
      localStorage.getItem(staticStandaloneKey);
    if (!raw) return cloneLayout(templateNo);
    const saved = JSON.parse(raw);
    const base = cloneLayout(templateNo);
    const merged = {
      ...base,
      ...saved,
      photo: { ...base.photo, ...(saved.photo || {}) },
      text: { ...base.text, ...(saved.text || {}) }
    };
    const fixedSizes = {
      leaderNameBox: 23,
      leaderCityBox: 22,
      achieverNameBox: 20,
      achieverRankBox: 13,
      phoneBox: 14
    };
    Object.entries(fixedSizes).forEach(([key, min]) => {
      const box = merged.text[key] || {};
      const current = Number(box.style?.fontSize ?? box.size ?? min);
      const size = min;
      merged.text[key] = { ...box, size, style: { ...(box.style || {}), fontSize: size } };
    });
    return merged;
  } catch {
    return cloneLayout(templateNo);
  }
};

const CalibrationOverlay = ({ layout, onChange, visible }) => {
  const dragRef = useRef(null);

  useEffect(() => {
    if (!visible) return undefined;

    const move = (event) => {
      const state = dragRef.current;
      if (!state) return;

      const poster = state.el?.closest?.('.aarsh-poster-shell');
      if (!poster) return;
      const rect = poster.getBoundingClientRect();

      const dx = (event.clientX - state.startX) * (1067 / rect.width);
      const dy = (event.clientY - state.startY) * (1600 / rect.height);

      const base = state.original;
      let next = { ...base };

      if (state.mode === 'resize') {
        next.w = Math.max(40, base.w + dx);
        next.h = Math.max(24, base.h + dy);
      } else {
        next.x = Math.max(0, Math.min(1067 - base.w, base.x + dx));
        next.y = Math.max(0, Math.min(1600 - base.h, base.y + dy));
      }

      onChange(state.key, next);
    };

    const up = () => {
      dragRef.current = null;
      document.body.style.userSelect = '';
    };

    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', up);
    return () => {
      window.removeEventListener('pointermove', move);
      window.removeEventListener('pointerup', up);
      document.body.style.userSelect = '';
    };
  }, [visible, onChange]);

  if (!visible) return null;

  const items = [
    ['leaderNameBox', 'LEADER NAME', 'name'],
    ['leaderCityBox', 'LEADER CITY', 'city'],
    ['achieverNameBox', 'ACHIEVER NAME', 'achiever'],
    ['achieverRankBox', 'ACHIEVER RANK', 'rank'],
    ['phoneBox', 'PHONE', 'phone']
  ];

  const photoItems = [
    ['leaderCircle', 'LEADER PHOTO', 'photo-leader'],
    ['achieverCircle', 'ACHIEVER PHOTO', 'photo-achiever']
  ];

  const startDrag = (event, key, mode, original) => {
    if (event.button !== 0) return;
    event.preventDefault();
    event.stopPropagation();
    dragRef.current = {
      key,
      mode,
      original: { ...original },
      startX: event.clientX,
      startY: event.clientY,
      el: event.currentTarget
    };
    document.body.style.userSelect = 'none';
  };

  const renderBox = ([key, label, kind]) => {
    const box = layout.text[key];
    return (
      <div
        key={key}
        className={`aarsh-calibration-box ${kind}`}
        style={{
          left: `${(box.x / 1067) * 100}%`,
          top: `${(box.y / 1600) * 100}%`,
          width: `${(box.w / 1067) * 100}%`,
          height: `${(box.h / 1600) * 100}%`
        }}
        onPointerDown={(e) => startDrag(e, key, 'move', box)}
      >
        <span>{label}</span>
        <b
          className="aarsh-calibration-resize"
          onPointerDown={(e) => startDrag(e, key, 'resize', box)}
        />
      </div>
    );
  };

  const renderPhoto = ([key, label, kind]) => {
    const box = layout.photo[key];
    return (
      <div
        key={key}
        className={`aarsh-calibration-box ${kind}`}
        style={{
          left: `${(box.x / 1067) * 100}%`,
          top: `${(box.y / 1600) * 100}%`,
          width: `${(box.w / 1067) * 100}%`,
          height: `${(box.h / 1600) * 100}%`
        }}
        onPointerDown={(e) => startDrag(e, key, 'move', box)}
      >
        <span>{label}</span>
        <b
          className="aarsh-calibration-resize"
          onPointerDown={(e) => startDrag(e, key, 'resize', box)}
        />
      </div>
    );
  };

  return (
    <div className="aarsh-calibration-overlay" aria-label="Template calibration overlay">
      {photoItems.map(renderPhoto)}
      {items.map(renderBox)}
    </div>
  );
};

const PhotoStylePicker = ({ selected, onSelect, onRemoveBackground, bgReady, bgLoading, role }) => (
  <div className="aarsh-photo-style-picker mt-3 mb-5">
    <div className="aarsh-photo-style-head">
      <div>
        <p>PHOTO STYLE</p>
        <strong>Choose how this photo should appear</strong>
      </div>
      <span>2 OPTIONS</span>
    </div>
    <div className="aarsh-photo-style-grid aarshtwo-option-grid">
      {PHOTO_STYLE_OPTIONS.map((option) => {
        const isCutout = option.id === 2;
        const isDisabled = isCutout && bgLoading;
        return (
          <button
            key={option.id}
            type="button"
            disabled={isDisabled}
            onClick={() => isCutout ? onRemoveBackground() : onSelect(1)}
            className={`aarsh-photo-style-option ${selected === option.id ? 'is-selected' : ''} ${isDisabled ? 'is-disabled' : ''}`}
          >
            <span className="aarsh-photo-style-number">{option.short}</span>
            <span className={`aarsh-photo-style-icon ${option.id === 1 ? 'is-original' : 'is-cutout'}`}>{option.id === 1 ? '🖼️' : '✂️'}</span>
            <span className="aarsh-photo-style-label">{isCutout && bgLoading ? 'Removing Background…' : option.label}</span>
            {selected === option.id && <span className="aarsh-photo-style-check">✓</span>}
          </button>
        );
      })}
    </div>
    {!bgReady && !bgLoading && <div className="aarsh-photo-style-loading">Original photo is ready. Choose <b>Remove BG</b> only if you want the background removed.</div>}
    {bgLoading && <div className="aarsh-photo-style-loading">Removing background… the editor stays available while it processes.</div>}
  </div>
);

