  const buyCredits = async (plan) => {

    if (!window.Razorpay) {
      alert("Razorpay SDK fail to load!");
      return;
    }

    try {

      const res = await fetch(`${BACKEND_URL}/create-order`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          amount: plan.price
        })
      });

      const order = await res.json();

      if (!order.id) {
        alert(
          "Order initialization failed: " +
          (order.error || "Unknown error")
        );
        return;
      }

      const options = {

        key: order.key_id,
        amount: order.amount,
        currency: "INR",

        name: "Aarsh Digital",

        description: `${plan.points} Points Pack`,

        order_id: order.id,

        prefill: {
          name: user?.displayName || "Aarsh Digital User",
          email: user?.email || "",
          contact: ""
        },

        handler: async function (response) {

          const verifyRes = await fetch(
            `${BACKEND_URL}/verify-payment`,
            {
              method: 'POST',

              headers: {
                'Content-Type': 'application/json'
              },

              body: JSON.stringify({
                ...response,
                uid: user.uid,
                points: plan.points
              })
            }
          );

          const data = await verifyRes.json();

          if (data.success) {

            setPoints(data.newCredits);

            await addNotification({
              title: "Recharge Successful",
              message: `₹${plan.price} payment successful. ${plan.points} points were added to your account.`,
              type: "payment"
            });

            setShowRechargeModal(false);

            alert(
              `Payment Verified! ${plan.points} Points Added ✅`
            );

          } else {

            alert("Payment verification failed!");

          }
        },

        theme: {
          color: "#6D28D9"
        }
      };

      const rzp = new window.Razorpay(options);

      rzp.open();

    } catch (e) {

      alert(
        "Order initialization error: " +
        e.message
      );

    }
  };

