// =========================================================
// STANDALONE CALIBRATION ROUTE
// =========================================================
// ?calibrate=1 intentionally bypasses Firebase/login so the calibration
// workspace can always open locally. Normal app/auth flow remains unchanged.
function CalibrationStandalone() {
  const [rank, setRank] = useState(RANKS[0]);
  const [tpl, setTpl] = useState(1);
  const [layout, setLayout] = useState(() => cloneLayout(1));
  const [status, setStatus] = useState('');
  const [detecting, setDetecting] = useState(false);
  const [saved, setSaved] = useState(false);
  const posterRef = useRef(null);

  const posterUrl = `${CLOUDINARY_BASE}/${String(tpl).padStart(2, '0')}.png?v=20260928`;

  useEffect(() => {
    setLayout(loadCalibration(rank, tpl));
    setStatus('');
    setSaved(false);
  }, [rank, tpl]);

  const updateBox = (key, value) => {
    setLayout(prev => ({
      ...prev,
      text: prev.text && prev.text[key]
        ? { ...prev.text, [key]: value }
        : prev.text,
      photo: prev.photo && prev.photo[key]
        ? { ...prev.photo, [key]: value }
        : prev.photo
    }));
    setSaved(false);
  };

  const save = () => {
    try {
      localStorage.setItem(calibrationStorageKey(rank, tpl), JSON.stringify(layout));
      setSaved(true);
      setStatus(`✓ Saved: ${getRankSlug(rank)}_${tpl}`);
    } catch (e) {
      setStatus(`Save failed: ${e.message}`);
    }
  };

  const reset = () => {
    setLayout(cloneLayout(tpl));
    setSaved(false);
    setStatus('Reset to baseline coordinates.');
  };

  const detectCircles = async () => {
    setDetecting(true);
    setStatus('Detecting Leader + Achiever photo rings…');
    try {
      const res = await fetch(`${BACKEND_URL}/detect-layout`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image_url: posterUrl, template: tpl, rank })
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || `HTTP ${res.status}`);
      const detected = data.layout || data;
      setLayout(prev => ({
        ...prev,
        photo: {
          ...prev.photo,
          ...(detected.photo || {}),
          ...(detected.leaderCircle ? { leaderCircle: detected.leaderCircle } : {}),
          ...(detected.achieverCircle ? { achieverCircle: detected.achieverCircle } : {})
        }
      }));
      setSaved(false);
      setStatus('✓ Circle detection complete. Check the two rings, then Save Layout.');
    } catch (e) {
      // Detector failure must not blank the page; baseline remains editable.
      setStatus(`Auto detection failed: ${e.message}. Baseline circles are still editable.`);
    } finally {
      setDetecting(false);
    }
  };

  const openApp = () => {
    window.location.href = window.location.pathname;
  };

  return (
    <div className="aarsh-calibration-page">
      <header className="aarsh-calibration-header">
        <div>
          <div className="aarsh-calibration-eyebrow">AARSH CREATIVE STUDIO</div>
          <h1>Template Calibration Studio</h1>
          <p>One-time alignment for text boxes + photo circles • 1067 × 1600</p>
        </div>
        <button type="button" onClick={openApp} className="aarsh-calibration-exit">← Back to Aarsh Digital</button>
      </header>

      <main className="aarsh-calibration-workspace">
        <aside className="aarsh-calibration-controls">
          <section className="aarsh-calibration-card">
            <label>RANK</label>
            <select value={rank} onChange={e => setRank(e.target.value)}>
              {RANKS.map(r => <option key={r} value={r}>{r}</option>)}
            </select>

            <label>TEMPLATE</label>
            <div className="aarsh-calibration-template-grid">
              {Array.from({ length: 15 }, (_, i) => i + 1).map(n => (
                <button
                  key={n}
                  type="button"
                  className={tpl === n ? 'selected' : ''}
                  onClick={() => setTpl(n)}
                >
                  <span>{STEP1_TEMPLATE_ICONS[n - 1] || '✦'}</span>
                  <small>T{n}</small>
                </button>
              ))}
            </div>
          </section>

          <section className="aarsh-calibration-card">
            <h2>Controls</h2>
            <button type="button" onClick={detectCircles} disabled={detecting} className="aarsh-calibration-primary">
              {detecting ? '⏳ Detecting Circles…' : '◎ Auto Detect Circles'}
            </button>
            <button type="button" onClick={save} className="aarsh-calibration-save">✓ Save Layout</button>
            <button type="button" onClick={reset} className="aarsh-calibration-reset">↺ Reset</button>
            <div className="aarsh-calibration-status">{status || 'Drag a box to move it. Drag its corner to resize.'}</div>
            {saved && <div className="aarsh-calibration-saved">Layout saved in this browser.</div>}
          </section>

          <section className="aarsh-calibration-help">
            <b>How to calibrate</b>
            <ol>
              <li>Select rank + template.</li>
              <li>Run Auto Detect Circles.</li>
              <li>Drag/resize the 7 overlays to match the design.</li>
              <li>Save Layout.</li>
            </ol>
          </section>
        </aside>

        <section className="aarsh-calibration-preview-card">
          <div className="aarsh-calibration-preview-head">
            <div><strong>{getRankSlug(rank)}_{tpl}.png</strong><span>Template {tpl} • {rank}</span></div>
            <span className="aarsh-calibration-size">1067 × 1600</span>
          </div>

          <div className="aarsh-calibration-canvas-wrap">
            <div ref={posterRef} className="aarsh-poster-shell aarsh-calibration-poster">
              <img
                key={posterUrl}
                src={posterUrl}
                alt="Calibration template"
                crossOrigin="anonymous"
                loading="eager"
                decoding="sync"
                fetchPriority="high"
              />
              <CalibrationOverlay layout={layout} onChange={updateBox} visible={true} />
            </div>
          </div>

          <div className="aarsh-calibration-legend">
            <span>🔵 Photo circles</span>
            <span>🟣 Text zones</span>
            <span>Drag = move</span>
            <span>Corner handle = resize</span>
          </div>
        </section>
      </main>
    </div>
  );
}

const CUSTOMER_TEXT_DEFAULT_SIZES = {
  // Step 2/3 baseline intentionally matches the current Step-1 reference values.
  // The +/- controls can still adjust these values afterward.
  leaderNameBox: 23,
  leaderCityBox: 22,
  achieverNameBox: 20,
  achieverRankBox: 13,
  phoneBox: 14
};

const normalizeCustomerLayout = (layout) => {
  const base = cloneLayout(1);
  const merged = {
    ...base,
    ...layout,
    photo: { ...base.photo, ...(layout?.photo || {}) },
    text: { ...base.text, ...(layout?.text || {}) }
  };
  Object.entries(CUSTOMER_TEXT_DEFAULT_SIZES).forEach(([key, size]) => {
    merged.text[key] = { ...merged.text[key], size };
    const style = merged.text[key].style || {};
    merged.text[key].style = { ...style, fontSize: size };
  });
  merged.photo = { ...merged.photo, leaderCircle: { ...merged.photo.leaderCircle, y: 247 } };
  return merged;
};

export default function App() {
  const params = typeof window !== 'undefined' ? new URLSearchParams(window.location.search) : null;
  const calibrationMode = params?.get('calibrate') === '1';
  const leaderStyleMode = params?.get('leaderstyle') === '1';
  if (leaderStyleMode) return <LeaderStyleDemo />;
  return calibrationMode ? <CalibrationStandalone /> : <AarshApp />;
}

